git checkout -b fix/issue-7-session-refresh-loop && cat > src/auth.js <<'EOF'
// Refreshes the session when its cookie expired.
// fetchSession() supplies a new session; it is injected because the
// repo does not define it yet.
export function refresh(session, fetchSession) {
  if (session.expired) return fetchSession();
  return session;
}
EOF
node --input-type=module -e "
import { refresh } from './src/auth.js';
const fresh = { expired: false, id: 'new' };
console.log(refresh({ expired: true }, () => fresh) === fresh ? 'expired -> fetched: ok' : 'FAIL');
const live = { expired: false };
console.log(refresh(live, () => { throw new Error('should not fetch'); }) === live ? 'live -> reused: ok' : 'FAIL');
"
